"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[473],{16107(e,t,o){o.r(t),o.d(t,{assets:()=>h,contentTitle:()=>i,default:()=>c,frontMatter:()=>s,metadata:()=>r,toc:()=>l});var n=o(74848),a=o(28453);const s={title:"Errors Used to Be Out in the Open: How AI Removed the Verification Layer Self-Taught Programmers Relied On",date:new Date("2026-11-12T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"self-taught-learning",category:"\u6559\u80b2\u8207\u52de\u52d5",article_tags:{zh:["\u81ea\u5b78\u7a0b\u5f0f","Stack Overflow","\u516c\u958b\u9a57\u8b49","AI \u5b78\u7fd2","\u5224\u65b7\u529b"],en:["self-taught-programming","stack-overflow","public-verification","learning-with-ai","judgement"]},keywords:["Stack Overflow","Tailwind CSS","Sangokushi Eiketsuden","PC Tools","paid coding courses","bookstore browsing","Game to Win"],summary:"Stack Overflow's value was never the answer but the public verification layer around it: votes, comments, dates, versions, objections. AI removed exactly that layer, shifting the cost of verification onto the beginners least able to bear it. Public discussion has been killed by its cost structure and trust has retreated into paid circles; the way out is to master one discipline first and build judgement that doesn't depreciate with each new version.",status:"published",reading_time:15,sidebar_label:"Errors Used to Be Out in the Open: How AI Removed the Verification Layer Self-Taught Programmers Relied On",sidebar_position:20261112,description:"Stack Overflow's value was never the answer but the public verification layer around it: votes, comments, dates, versions, objections. AI removed exactly that layer, shifting the cost of verification onto the beginners least able to bear it. Public discussion has been killed by its cost structure and trust has retreated into paid circles; the way out is to master one discipline first and build judgement that doesn't depreciate with each new version.",slug:"/notes/errors-used-to-be-out-in-the-open"},i="Errors Used to Be Out in the Open: How AI Removed the Verification Layer Self-Taught Programmers Relied On",r={id:"notes/2026Q4/\u932f\u8aa4\u66fe\u7d93\u662f\u6524\u958b\u7684",title:"Errors Used to Be Out in the Open: How AI Removed the Verification Layer Self-Taught Programmers Relied On",description:"Stack Overflow's value was never the answer but the public verification layer around it: votes, comments, dates, versions, objections. AI removed exactly that layer, shifting the cost of verification onto the beginners least able to bear it. Public discussion has been killed by its cost structure and trust has retreated into paid circles; the way out is to master one discipline first and build judgement that doesn't depreciate with each new version.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/notes/2026Q4/\u932f\u8aa4\u66fe\u7d93\u662f\u6524\u958b\u7684.md",sourceDirName:"notes/2026Q4",slug:"/notes/errors-used-to-be-out-in-the-open",permalink:"/en/docs/notes/errors-used-to-be-out-in-the-open",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:20261112,frontMatter:{title:"Errors Used to Be Out in the Open: How AI Removed the Verification Layer Self-Taught Programmers Relied On",date:"2026-11-12T00:00:00.000Z",lang:"en",section:"sober-record",topic:"self-taught-learning",category:"\u6559\u80b2\u8207\u52de\u52d5",article_tags:{zh:["\u81ea\u5b78\u7a0b\u5f0f","Stack Overflow","\u516c\u958b\u9a57\u8b49","AI \u5b78\u7fd2","\u5224\u65b7\u529b"],en:["self-taught-programming","stack-overflow","public-verification","learning-with-ai","judgement"]},keywords:["Stack Overflow","Tailwind CSS","Sangokushi Eiketsuden","PC Tools","paid coding courses","bookstore browsing","Game to Win"],summary:"Stack Overflow's value was never the answer but the public verification layer around it: votes, comments, dates, versions, objections. AI removed exactly that layer, shifting the cost of verification onto the beginners least able to bear it. Public discussion has been killed by its cost structure and trust has retreated into paid circles; the way out is to master one discipline first and build judgement that doesn't depreciate with each new version.",status:"published",reading_time:15,sidebar_label:"Errors Used to Be Out in the Open: How AI Removed the Verification Layer Self-Taught Programmers Relied On",sidebar_position:20261112,description:"Stack Overflow's value was never the answer but the public verification layer around it: votes, comments, dates, versions, objections. AI removed exactly that layer, shifting the cost of verification onto the beginners least able to bear it. Public discussion has been killed by its cost structure and trust has retreated into paid circles; the way out is to master one discipline first and build judgement that doesn't depreciate with each new version.",slug:"/notes/errors-used-to-be-out-in-the-open"},sidebar:"lucidRecord",previous:{title:"An Engineer's Sense of Security Shouldn't Come from Writing the Code Yourself, but from a Trail No One Can Alter",permalink:"/en/docs/notes/security-from-an-unalterable-trail"},next:{title:"Why I Rarely Write About Psychology",permalink:"/en/docs/TechNotes/\u6211\u5f88\u5c11\u8ac7\u5fc3\u7406\u5b78"}},h={},l=[{value:"The years when learning cost nothing",id:"the-years-when-learning-cost-nothing",level:2},{value:"What stood behind an accepted answer",id:"what-stood-behind-an-accepted-answer",level:2},{value:"What AI removed was not the answer but the verification layer",id:"what-ai-removed-was-not-the-answer-but-the-verification-layer",level:2},{value:"Three generations of friction: DOS, save files, Stack Overflow",id:"three-generations-of-friction-dos-save-files-stack-overflow",level:2},{value:"Why it can&#39;t be rebuilt",id:"why-it-cant-be-rebuilt",level:2},{value:"Trust becomes a product: what a NT$10,000 HTML course is really selling",id:"trust-becomes-a-product-what-a-nt10000-html-course-is-really-selling",level:2},{value:"The way out: master one discipline first",id:"the-way-out-master-one-discipline-first",level:2},{value:"Conclusion",id:"conclusion",level:2}];function d(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"errors-used-to-be-out-in-the-open-how-ai-removed-the-verification-layer-self-taught-programmers-relied-on",children:"Errors Used to Be Out in the Open: How AI Removed the Verification Layer Self-Taught Programmers Relied On"})}),"\n",(0,n.jsx)(t.p,{children:"@Mythogen Engine \xb7 12 November 2026"}),"\n",(0,n.jsx)(t.h2,{id:"the-years-when-learning-cost-nothing",children:"The years when learning cost nothing"}),"\n",(0,n.jsx)(t.p,{children:"More than a decade ago, online courses were just taking off and Stack Overflow was at its peak. It was a golden age for engineers teaching themselves. There was even a shared belief that learning to code didn't require money at all \u2014 and that not paying actually made you learn deeper and more solidly, because you were forced to deal with the low-level details yourself."}),"\n",(0,n.jsx)(t.p,{children:"Java, JavaScript, Python: I taught myself all of them that way. I can't say exactly how far self-teaching can take you, but back then it was at least enough. I haven't written much by hand in recent years. Ask me to solve the simplest LeetCode problem from scratch today and I would probably have to look up the syntax, and I might not remember some of the logic rules either."}),"\n",(0,n.jsx)(t.p,{children:"But writing code semi-automatically with AI, I have no trouble at all. The syntax goes to the AI; my job is to judge: is what it gave me right, where is it wrong, which direction should I fix it in. Syntax rusts. That kind of judgement doesn't. And it is exactly that judgement that decides whether AI is an accelerator for you or an oracle."}),"\n",(0,n.jsx)(t.p,{children:"This has limits, of course. For tools, websites and scripts I build for myself, this approach is more than enough. Large-scale collaboration is another matter: it involves team conventions, the history of a codebase and review processes, none of which personal judgement or AI can fill in. This essay is about the first case \u2014 how one person develops judgement that doesn't rust."}),"\n",(0,n.jsx)(t.p,{children:"AI has made everything much more convenient. But honestly, something is missing: the solid footing I used to feel while living on Stack Overflow. This essay takes that feeling apart to see what it actually was, who took it away, and why it can't be brought back."}),"\n",(0,n.jsx)(t.h2,{id:"what-stood-behind-an-accepted-answer",children:"What stood behind an accepted answer"}),"\n",(0,n.jsx)(t.p,{children:"Stack Overflow's real value was never the answer itself. It was the layer of public verification around the answer."}),"\n",(0,n.jsx)(t.p,{children:"An accepted answer had a vote count beneath it, telling you how many people had tried it and found it worked. Below that were the comments: someone pointing out that a certain line breaks in a newer version, someone adding another way to do it, someone flatly disagreeing. The answer carried a date and an edit history, and sometimes a note saying \u201cthis only works in Python 2\u201d. You didn't just see an answer. You saw an argument that had already been fought out, with every side's case laid open."}),"\n",(0,n.jsx)(t.p,{children:"More importantly, the community forced you to improve. Ask something vague and the first comment would almost certainly be \u201cwhich version are you using?\u201d Fail to add the details and you'd be downvoted and your question closed. It stung, but after a few times you learned to state your version, environment and error message clearly the first time."}),"\n",(0,n.jsx)(t.p,{children:"So Stack Overflow always had two kinds of people: those who stated their version when asking, and those who just typed \u201cwhy doesn't this work\u201d; those who noted when an answer applied, and those who pasted a block of code and left. Experienced people already add the version when they search, and good answers state it too, so outdated answers don't come out on top. The ones who got caught were beginners who didn't yet know to add the version."}),"\n",(0,n.jsx)(t.p,{children:"But that dividing line was visible, and there was a path across it. Question by question, the community pushed people from vague to precise."}),"\n",(0,n.jsx)(t.h2,{id:"what-ai-removed-was-not-the-answer-but-the-verification-layer",children:"What AI removed was not the answer but the verification layer"}),"\n",(0,n.jsx)(t.p,{children:"The hidden cost of AI lies in the credibility of its answers."}),"\n",(0,n.jsx)(t.p,{children:"Stack Overflow's credibility was visible and distributed: votes, comments, dates, versions and objections, all public. AI's credibility is invisible and centralised: a very confident voice gives you an answer, and nobody underneath says it's wrong."}),"\n",(0,n.jsx)(t.p,{children:"The cost of verification hasn't gone away. It has simply been shifted from the community back onto the user \u2014 and beginners are the people least able to bear it."}),"\n",(0,n.jsx)(t.p,{children:"A concrete example. Tailwind CSS changed its configuration significantly from v3 to v4: v4 configures directly in CSS and no longer uses tailwind.config.js by default. Ask an AI \u201chow do I configure Tailwind\u201d and it may well hand you a mix of both generations. Someone who knows CSS spots the problem at a glance. A beginner who has only learned Tailwind gets stuck, and doesn't know where."}),"\n",(0,n.jsx)(t.p,{children:"On Stack Overflow you could fall into the same trap, but afterwards you could find clues: the answer had a date, and someone had commented \u201cthis doesn't work in the new version\u201d. An AI answer has no date, no version label, no objection. Even if you state the version, it may quietly stitch the two versions' approaches together."}),"\n",(0,n.jsx)(t.p,{children:"There are no fewer errors than before. What has changed is that errors used to be laid out for everyone to see; now they come pre-packaged."}),"\n",(0,n.jsx)(t.p,{children:"There's an irony here too. AI grew up feeding on exactly those Stack Overflow answers. Once people switched to AI, fewer asked and fewer answered. Nobody is replenishing the commons, so questions about new versions and new frameworks lose that layer of public verification \u2014 and the next generation of AI has less to learn from."}),"\n",(0,n.jsx)(t.p,{children:"I recently came across an example. A university lecturer posted on social media that he had had AI build a locally runnable substitute for Cloudflare in an hour, and had published it to a public package registry. He wrote plainly that it was a first version and still missing a lot. The first comment underneath: \u201cAmazing.\u201d"}),"\n",(0,n.jsx)(t.p,{children:"What got built in an hour was the interface: code calls it exactly as it would call Cloudflare. But the hard part of platforms like this was never the interface. It is the promises behind it: what happens when data goes wrong, how consistency is kept across locations, how code uploaded by others is isolated. Knowing whether you got these right takes many people stumbling over them for a long time."}),"\n",(0,n.jsx)(t.p,{children:"The author's \u201cfirst version, still missing a lot\u201d is exactly the good Stack Overflow habit of stating where something applies. The problem is that it was drowned out by \u201cdone in an hour\u201d, and the response wasn't questions but applause. The old community would have asked: which cases have you tested? Now the response is a like."}),"\n",(0,n.jsx)(t.p,{children:"This is also where the line from the opening of this essay gets crossed. For a tool you use yourself, an hour of AI work is more than enough. But once it's on a public package registry, it may become the foundation of someone else's project. The cost of writing has dropped to an hour; the cost of verifying hasn't dropped with it. The commons isn't just going unreplenished \u2014 it is starting to fill up with things nobody has verified."}),"\n",(0,n.jsx)(t.h2,{id:"three-generations-of-friction-dos-save-files-stack-overflow",children:"Three generations of friction: DOS, save files, Stack Overflow"}),"\n",(0,n.jsx)(t.p,{children:"Go back further and the same pattern appears: friction forces people to develop depth, and once friction disappears, depth is no longer the default."}),"\n",(0,n.jsx)(t.p,{children:"When my generation played games, you first had to know DOS commands, or you couldn't even launch the game. If you wanted to modify a game, you used PC Tools to read hexadecimal, and along the way you naturally learned how files and memory work."}),"\n",(0,n.jsxs)(t.p,{children:["The easiest thing to modify back then was the save file. Older games weren't encrypted: artwork, text and saves all sat in folders where you could dump them, decode them, even edit them. With Koei's ",(0,n.jsx)(t.em,{children:"Sangokushi Eiketsuden"}),", almost the whole modding scene revolved around save files: change the stats, change the special moves, change the graphics. Kids knew no theory. They opened the folder, looked at how the files were arranged, guessed, changed a number, went back into the game and saw what changed. Get it wrong and the game crashed."]}),"\n",(0,n.jsx)(t.p,{children:"That cycle of guess, change, test and observe is the most primitive form of the scientific method. And the judge was the machine itself: you knew immediately whether you were right. Just like Stack Overflow, the errors were laid out in front of you."}),"\n",(0,n.jsx)(t.p,{children:"Most games today are locked down. This isn't just technical progress; there's a very clear commercial reason behind it. Once in-game currency can be bought with real money, the save file becomes money. Editing your save is stealing their revenue. So saves moved to servers, got encrypted, got anti-cheat. The sandbox didn't disappear naturally. It was sealed off by the business model."}),"\n",(0,n.jsx)(t.p,{children:"To be fair, modding culture still exists, and many games ship official mod tools and workshops. But those are officially sanctioned playgrounds with fences around them, which is a different thing from digging through folders and guessing the structure yourself."}),"\n",(0,n.jsx)(t.p,{children:"The small minority who dig deep hasn't disappeared. Modders, dataminers and speedrunners go deeper than anyone did back then. What has changed is the middle layer. Ordinary players used to be pushed half a step towards the low level by friction; now only the two ends remain \u2014 a very few go very deep, and most never touch it. It's the same split as the two kinds of people on Stack Overflow who did or didn't state their version."}),"\n",(0,n.jsx)(t.p,{children:"Games went from open to closed, knowledge went from public verification to a black box, and AI itself is a box you can't see inside. All three point in the same direction: fewer and fewer places where learners can open things up and look for themselves."}),"\n",(0,n.jsx)(t.h2,{id:"why-it-cant-be-rebuilt",children:"Why it can't be rebuilt"}),"\n",(0,n.jsx)(t.p,{children:"Recreating Stack Overflow is probably impossible. Could AI bring back the old model of public discussion and public recommendation? Say, by turning AI answers into public objects that people can vote on, annotate, and mark as \u201cwrong for v4\u201d?"}),"\n",(0,n.jsx)(t.p,{children:"Technically, yes. But there are four dead ends."}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"First, discussion was never the goal; it was the price."})," Nobody wanted to discuss things back then. You just couldn't get an answer without asking. Asking, answering, being corrected \u2014 the public record was a by-product. Once AI removed the price, the by-product went with it. When there's a direct answer, what's left to discuss? So simply \u201cbuilding a better forum\u201d won't work, because nobody has a reason to pay that price any more."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Second, the incentive is gone."})," Answering on Stack Overflow earned you reputation that went on your CV and helped you get hired. Verifying AI answers today earns you neither name nor money \u2014 and you're helping someone else improve their product."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Third, platforms have no motive."})," A system that publicly records an AI's mistakes is a liability for the company selling the AI. They would rather you quietly click \u201cthumbs down\u201d."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Fourth, and most fatal: the cost structure has flipped."})," The old internet had less spam and fewer attacks, and moderation had the resources to deal with them. A human posted one piece of junk, a moderator deleted one, at roughly equal cost. Today AI produces junk at near-zero cost, while moderation still needs people. Attackers use machines, defenders use humans, and that war can't be won. Stack Overflow itself had to ban ChatGPT-generated answers at the end of 2022, precisely because moderators couldn't keep up with the volume. Today spam, advertising and attacks are everywhere, and no forum survives easily."]}),"\n",(0,n.jsx)(t.p,{children:"The bigger irony is that a forum dedicated to verifying AI answers would become the biggest target of all. The fake votes and fake comments attacking it would themselves be AI-generated. The verification layer would be contaminated by the very thing it is trying to verify \u2014 a self-referential trap."}),"\n",(0,n.jsx)(t.p,{children:"In programming circles this trap has already appeared in another form. The fashionable approach now is to have multiple agents review each other's work so humans no longer need to look. Someone in one discussion put it bluntly: if five AIs can't find a problem, no human will either. Others argue that the technical guidance humans give AI is outdated and full of their own blind spots, so it's better not to teach it at all."}),"\n",(0,n.jsx)(t.p,{children:"But Stack Overflow's verification worked because the verifiers were independent of each other: people on different versions, in different environments, with different experience, each tried it and laid out their results. Several agents built from similar training material are more like one person looking in the mirror several times \u2014 they share the same blind spots. As for humans being more outdated, the Tailwind example above already shows that AI can't tell which version it's in either. The verification layer hasn't been rebuilt. It has just been moved into another box you can't see inside."}),"\n",(0,n.jsx)(t.p,{children:"Discussion hasn't completely died. It has moved into Discord, Slack and internal company groups. Those places aren't searchable and aren't public, so the next generation of people can't find them, and the next generation of AI can't learn from them. Knowledge has gone from commons back to private property."}),"\n",(0,n.jsx)(t.p,{children:"Trustworthy verification can only retreat into closed circles: invitation-only, real-name, paid groups. So we come full circle: trustworthy information now requires an entry fee. Trust has gone from a public good to a ticket."}),"\n",(0,n.jsx)(t.h2,{id:"trust-becomes-a-product-what-a-nt10000-html-course-is-really-selling",children:"Trust becomes a product: what a NT$10,000 HTML course is really selling"}),"\n",(0,n.jsx)(t.p,{children:"In the AI era, courses that fleece beginners are back in force, and that is no coincidence."}),"\n",(0,n.jsx)(t.p,{children:"When Stack Overflow was around, who needed to pay for a cram class to learn web development? Now people dare to charge over NT$10,000 to teach the most basic HTML and CSS, things with no barrier to entry at all. It's quite possible the instructors themselves haven't kept up with the technology."}),"\n",(0,n.jsx)(t.p,{children:"But students still buy. Because once the public layer of trust collapsed, trust itself became something you can sell. A NT$10,000 HTML course isn't really selling HTML. It's selling \u201csomeone who vouches for you\u201d. Students pay for certainty, and they have no ability to judge whether the instructor is keeping up."}),"\n",(0,n.jsx)(t.p,{children:"There's a very ironic point here. The HTML and CSS these courses teach are precisely the most stable parts, the least version-dependent, documented clearly and for free in the official references. CSS written over a decade ago still works today. Version problems live mainly in the framework layer."}),"\n",(0,n.jsx)(t.p,{children:"And the framework layer is also the easiest to harvest: every new version lets a course \u201cupdate\u201d and charge again. People who learn a framework without understanding what's underneath have knowledge that depreciates version by version."}),"\n",(0,n.jsx)(t.p,{children:"I know both Tailwind and plain CSS, but I prefer plain CSS because what I build often really does need to last a long time. For something you hand off when done, that many people work on together, or that might be torn down and rebuilt in a few months, Tailwind makes good sense: fast, consistent, easy to collaborate on. But for something that needs to last, every extra layer of dependency is one more thing that can break: build tools need upgrading, frameworks change syntax, documentation moves. Plain CSS needs no build step. If the browser can read it, it works, and it will still work when you open it five years from now."}),"\n",(0,n.jsx)(t.p,{children:"This isn't about whether you know the tools. It's about choosing tools by lifespan."}),"\n",(0,n.jsx)(t.h2,{id:"the-way-out-master-one-discipline-first",children:"The way out: master one discipline first"}),"\n",(0,n.jsxs)(t.p,{children:["This brings me back to my earlier essay, ",(0,n.jsx)(t.em,{children:"Cognition and Judgment"}),". Before learning something, you first need to find a way to build your cognition of, and judgement about, that discipline. Otherwise no course or book can help you."]}),"\n",(0,n.jsx)(t.p,{children:"But there's a chicken-and-egg problem: you need judgement to choose how to learn well, and judgement is itself learned. On day one, a beginner has none."}),"\n",(0,n.jsx)(t.p,{children:"The community used to solve this for you. Votes, comments, \u201cwhich version are you using?\u201d \u2014 the community was effectively lending you its judgement, like scaffolding, so you could build your own as you learned and drop the scaffolding once you'd learned enough. Now the scaffolding is gone and beginners can only buy it. That is exactly what the NT$10,000 course sells. The problem is that someone without judgement can't tell whether the scaffolding is real."}),"\n",(0,n.jsx)(t.p,{children:"My answer is this: a beginner's first scaffolding doesn't have to be bought. It can be another discipline you have already mastered."}),"\n",(0,n.jsx)(t.p,{children:"The underlying principles of all knowledge and disciplines should be similar. Once you've mastered an art or a discipline and truly understand its principles, that cognition and judgement can be carried into learning elsewhere. When I moved from embedded systems to teaching myself Java, JavaScript and Python, what I relied on wasn't a cram school but already knowing what the structure of learning something looks like."}),"\n",(0,n.jsx)(t.p,{children:"Looking back, this is how my own path went. Studying in Australia, Chinese books were hard to come by, but there was a huge bookstore in the city centre where you could browse and buy English books freely. Learning embedded systems \u2014 ARM, RTOS, C \u2014 I would first ask a professor which book was good, then go and browse. I usually bought whatever the professors recommended. One specialist book couldn't be found anywhere in Australia; I had to have the University of Queensland bookshop order it from the Oxford University bookshop in England."}),"\n",(0,n.jsx)(t.p,{children:"I preferred university-press books \u2014 McGraw-Hill, Stanford, MIT \u2014 and rarely read O'Reilly-style practical books. For every discipline I learned, I had at least one book dedicated to the foundations. University presses usually publish these as a set of three \u2014 Fundamentals, Advanced, Expert \u2014 plus one big complete volume. Books were simply too expensive, so I usually bought only the complete volume and read the three-book set in the library. Which assumes your university has a very good library."}),"\n",(0,n.jsx)(t.p,{children:"The three-book set is itself a map: what to learn first, what next, and how far you need to go before you can call it deep. Practical books and AI answers are recipes. Foundational books give you the skeleton."}),"\n",(0,n.jsx)(t.p,{children:"So those years when learning \u201ccost nothing\u201d weren't actually free. Professors, libraries, university bookshops, Stack Overflow \u2014 all were commons that someone else paid for. The golden age wasn't a time when learning had no cost; it was a time when public infrastructure bore the cost. A professor recommending a book usually gets no commission. The person recommending a course to you today is often the one selling it. Whether the recommender has a stake is what decides whether that layer of verification can be trusted."}),"\n",(0,n.jsx)(t.p,{children:"Where can you start today? Browse in the few bookstores that remain \u2014 Tenlong Books in Taipei, for example \u2014 or use online bookstores' previews. There's plenty of junk among new books now too, but the point is that you can look before you buy. Pick three books you trust, read them, get a basic grasp and baseline judgement, and then work out how to keep learning."}),"\n",(0,n.jsx)(t.p,{children:"Where the three books agree is the stable foundation of the discipline; where they disagree is where you have to judge for yourself. It's the same principle as reading several answers on Stack Overflow. Browsing has one more key advantage: you verify first and pay later. The NT$10,000 course is the opposite \u2014 you pay first and only find out afterwards whether it was worth it."}),"\n",(0,n.jsx)(t.p,{children:"Mastering one discipline doesn't transfer automatically, though. Plenty of experts are excellent in their own field and fall into the same traps in another, because they know how to do things but have never reflected on how they learned them. To transfer, you have to be able to see the structure of your own learning."}),"\n",(0,n.jsxs)(t.p,{children:["That is exactly what my book ",(0,n.jsx)(t.em,{children:"Game to Win"})," sets out to do. The new generation of gamers doesn't need to study computers or the low level the way mine did, and players who dig into these things were always a minority. So the book doesn't assume readers already understand the low level. Instead it offers a view of the whole from the top down: how the industry, design and economics lock together. You don't need to go through the friction of the DOS era to see the structure. It isn't a book about playing games; it's an example of how to build an overall perspective."]}),"\n",(0,n.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,n.jsx)(t.p,{children:"The solid footing I felt back on Stack Overflow didn't come from the answers, it turns out. It came from the errors. The errors were laid out there; someone pointed them out, someone pushed back, you could see how they went wrong, and slowly you learned to tell for yourself."}),"\n",(0,n.jsx)(t.p,{children:"The problem today isn't that people have become lazy and stopped discussing. It's that the environment for public discussion has been killed by its cost structure. Trust has retreated into closed circles and become a ticket you pay for."}),"\n",(0,n.jsx)(t.p,{children:"That leaves only two choices: pay to get into a circle, or train yourself until you can verify on your own. The second path is slower, but what it builds doesn't depreciate with each new version."})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,t,o){o.d(t,{R:()=>i,x:()=>r});var n=o(96540);const a={},s=n.createContext(a);function i(e){const t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);